QS = [
    ('Hakeem Force Academy', 'In which battle did the Muslims dig a trench around Madinah?', ['Badr', 'Uhud', 'Khandaq (Ahzab)', 'Hunain'], 2, 'The Muslims dug a trench around Madinah in the Battle of Khandaq (Ahzab) in 5 AH on the advice of Salman Farsi. It stopped the Quraysh and their allies from attacking the city.', 'The Battle of Khandaq is also called the Battle of the Confederates (Ahzab).', 10),
    ('Hakeem Force Academy', 'In which battle was Abu Jahl killed?', ['Uhud', 'Badr', 'Khandaq', 'Khyber'], 1, 'Abu Jahl, a leader of the Quraysh, was killed in the Battle of Badr in 2 AH. He was struck down by two young Ansari brothers, Muadh and Muawwidh.', "Abu Jahl's real name was Amr ibn Hisham.", 14),
    ('Hakeem Force Academy', 'In which battle was Hazrat Hamza (RA) martyred?', ['Badr', 'Uhud', 'Khandaq', 'Mutah'], 1, "Hazrat Hamza (RA), uncle of the Prophet (PBUH), was martyred in the Battle of Uhud in 3 AH. He was killed by Wahshi, a slave of Jubayr ibn Mut'im.", 'Hazrat Hamza (RA) is known as Asadullah and Sayyid ush-Shuhada (Chief of the Martyrs).', 14),
    ('Hakeem Force Academy', 'In which battle was Hazrat Jafar Tayyar (RA) martyred?', ['Battle of Mutah', 'Battle of Uhud', 'Battle of Tabuk', 'Battle of Hunain'], 0, 'Hazrat Jafar ibn Abi Talib (RA) was one of the three commanders martyred in the Battle of Mutah in 8 AH. He is called Tayyar (the flyer) because he is said to have been given wings in Paradise.', 'The other two commanders at Mutah were Zaid bin Haritha and Abdullah bin Rawaha (RA).', 7),
    ('Hakeem Force Academy', 'Near which city in Punjab are the ruins of the Indus Valley site of Harappa?', ['Multan', 'Lahore', 'Sahiwal', 'Bahawalpur'], 2, 'The ruins of Harappa lie near the town of Harappa in Sahiwal district of Punjab, Pakistan. The site was first excavated in the 1920s.', 'Mohenjo-daro, the other great Indus Valley city, is in Larkana district of Sindh.', 3),
    ('Hakeem Force Academy', 'In which city of India is Jallianwala Bagh located?', ['Ludhiana', 'Delhi', 'Amritsar', 'Jalandhar'], 2, 'Jallianwala Bagh is a public garden in Amritsar, Punjab, India. British troops under General Dyer fired on a crowd there on 13 April 1919.', 'The massacre took place on Baisakhi day in 1919.', 4),
    ('Hakeem Force Academy', 'In which city is the historic Bala Hisar Fort located?', ['Lahore', 'Peshawar', 'Multan', 'Quetta'], 1, 'Bala Hisar Fort stands in Peshawar, Khyber Pakhtunkhwa. It overlooks the old city.', 'The fort was rebuilt by the Sikhs in the early 19th century.', 2),
    ('Hakeem Force Academy', 'In which city is the Quaid-e-Azam Residency located?', ['Murree', 'Ziarat', 'Quetta', 'Swat'], 1, 'The Quaid-e-Azam Residency is in Ziarat, Balochistan. Quaid-e-Azam spent his last days there in 1948.', 'The Residency was originally built in 1892 as a British summer retreat.', 2),
    ('Hakeem Force Academy', 'Near which city is the Rohtas Fort located?', ['Lahore', 'Rawalpindi', 'Jhelum', 'Attock'], 2, 'Rohtas Fort is near Dina in Jhelum district, Punjab. Sher Shah Suri built it in the 16th century.', 'Rohtas Fort is a UNESCO World Heritage Site.', 3),
    ('Hakeem Force Academy', 'In which city is the shrine of Hazrat Mian Mir located?', ['Multan', 'Lahore', 'Sialkot', 'Peshawar'], 1, 'The shrine of the Sufi saint Hazrat Mian Mir is in Lahore. He is said to have laid the foundation stone of the Golden Temple in Amritsar.', 'The Mian Mir area of Lahore is named after him.', 5),
    ('Hakeem Force Academy', 'In which city is the Wazir Khan Mosque located?', ['Delhi', 'Multan', 'Lahore', 'Agra'], 2, 'The Wazir Khan Mosque stands in the walled city of Lahore. It was built in 1634-35 in the Mughal era.', 'It is famous for its Kashi tile work.', 3),
    ('Hakeem Force Academy', 'In which city is the Arfa Karim Tower located?', ['Karachi', 'Islamabad', 'Lahore', 'Faisalabad'], 2, 'The Arfa Karim Tower is in Lahore, Punjab, near Gulberg. It is named after the young computer prodigy Arfa Karim.', 'Arfa Karim was the youngest Microsoft Certified Professional.', 2),
    ('Hakeem Force Academy', 'In which city was the All India Muslim League founded in 1906?', ['Lahore', 'Dhaka', 'Delhi', 'Aligarh'], 1, 'The All India Muslim League was founded in Dhaka in December 1906 at the Muslim Educational Conference, hosted by Nawab Salimullah Khan.', 'Its first president was Nawab Viqar-ul-Mulk, and Sir Aga Khan was the first permanent president.', 2),
    ('Hakeem Force Academy', 'In which country does the Orange River mainly flow?', ['South Africa', 'Nigeria', 'Kenya', 'Egypt'], 0, 'The Orange River is the longest river in South Africa and flows westward to the Atlantic Ocean. It rises in the mountains of Lesotho.', 'It forms part of the border between South Africa and Namibia.', 2),
    ('Hakeem Force Academy', 'In which country is the volcano Mount Etna located?', ['Greece', 'Italy', 'Spain', 'Japan'], 1, 'Mount Etna is on the island of Sicily, Italy. It is one of the most active volcanoes in the world.', 'It is the highest active volcano in Europe.', 2),
    ('Hakeem Force Academy', 'In which country were the 2016 Olympic Games held?', ['Japan', 'China', 'Brazil', 'Britain'], 2, 'The 2016 Summer Olympics were held in Rio de Janeiro, Brazil.', 'They were the first Summer Olympics held in South America.', 2),
    ('Hakeem Force Academy', 'In which country were the Olympic Games postponed from 2020 and held in 2021 hosted?', ['China', 'Japan', 'Brazil', 'South Korea'], 1, 'The Tokyo Olympics, scheduled for 2020, were postponed because of Covid-19 and held in Japan in July-August 2021.', 'The next Summer Olympics after Tokyo were held in Paris in 2024.', 4),
    ('Hakeem Force Academy', 'In which direction of Pakistan is India located?', ['East', 'West', 'North', 'North-West'], 0, 'India lies along the eastern border of Pakistan.', 'The Pakistan-India border is about 2,900 km long.', 3),
    ('Hakeem Force Academy', 'In which direction of Pakistan is Iran located?', ['East', 'West', 'North', 'South'], 1, 'Iran lies to the west of Pakistan, bordering Balochistan.', 'Pakistan also shares borders with Afghanistan in the west and north-west and China in the north.', 2),
    ('Hakeem Force Academy', 'In which Chinese city did the Covid-19 outbreak first appear in December 2019?', ['Beijing', 'Shanghai', 'Wuhan', 'Guangzhou'], 2, 'The first cases of Covid-19 were reported in Wuhan, the capital of Hubei province, China, in December 2019.', 'The World Health Organization declared Covid-19 a pandemic in March 2020.', 2),
    ('Hakeem Force Academy', 'In which game is the agricultural shot played?', ['Hockey', 'Cricket', 'Football', 'Tennis'], 1, 'The agricultural shot is a cricket stroke in which the batsman swings the bat across the line in a cow-corner heave, like a farmer swinging a scythe.', 'It is usually aimed towards the cow corner region of the field.', 2),
    ('Hakeem Force Academy', 'In which Ghazwa did angels come to help the Muslims?', ['Badr', 'Khyber', 'Tabuk', 'Mutah'], 0, 'The Quran says that angels helped the Muslims in the Battle of Badr in 2 AH.', 'About 313 Muslims faced an army of roughly 1,000 Quraysh at Badr.', 2),
    ('Hakeem Force Academy', 'In which Ghazwa were the blessed teeth of the Prophet (PBUH) martyred?', ['Badr', 'Uhud', 'Khandaq', 'Hunain'], 1, "The Prophet's (PBUH) front tooth was broken and he was wounded in the Battle of Uhud in 3 AH.", 'The Battle of Uhud took place near Mount Uhud close to Madinah.', 5),
    ('Hakeem Force Academy', 'In which Hijri year did Hazrat Khalid bin Waleed (RA) accept Islam?', ['6 AH', '7 AH', '8 AH', '10 AH'], 2, 'Hazrat Khalid bin Waleed (RA) accepted Islam in 8 AH (629 CE), before the conquest of Makkah. Some sources give 7 AH, so sources differ, but 8 AH is the common textbook answer.', 'He was later given the title Saifullah (Sword of Allah).', 8),
    ('Hakeem Force Academy', 'In which Hijri year did the tragedy of Karbala take place?', ['40 AH', '61 AH', '50 AH', '72 AH'], 1, 'The martyrdom of Hazrat Hussain (RA) at Karbala took place on 10 Muharram 61 AH (680 CE).', 'Yazid ibn Muawiya was the Umayyad ruler at that time.', 4),
    ('Hakeem Force Academy', 'In which Hijri year was the Battle of Badr fought?', ['1 AH', '2 AH', '3 AH', '5 AH'], 1, 'The Battle of Badr was fought on 17 Ramadan 2 AH (624 CE).', 'It was the first major battle between Muslims and the Quraysh.', 2),
    ('Hakeem Force Academy', 'In which Hijri year was the Battle of Uhud fought?', ['2 AH', '3 AH', '4 AH', '5 AH'], 1, 'The Battle of Uhud was fought in Shawwal 3 AH (625 CE), after Badr.', 'The archers who left their post on the hill let the Quraysh cavalry attack from behind.', 15),
    ('Hakeem Force Academy', 'In which Hijri year was Makkah conquered?', ['6 AH', '7 AH', '8 AH', '10 AH'], 2, 'The Prophet (PBUH) conquered Makkah peacefully in Ramadan 8 AH (630 CE).', 'The conquest followed the Quraysh breaking the Treaty of Hudaibiya.', 4),
    ('Hakeem Force Academy', 'In which Hijri year was the Ghazwa of Khyber fought?', ['5 AH', '6 AH', '7 AH', '8 AH'], 2, 'The Battle of Khyber was fought in 7 AH (628 CE) against the Jewish fortresses north of Madinah.', 'Hazrat Ali (RA) is famous for conquering the fort of Qamus at Khyber.', 3),
    ('Hakeem Force Academy', 'In which Hijri year was the Treaty of Hudaibiya signed?', ['4 AH', '5 AH', '6 AH', '8 AH'], 2, 'The Treaty of Hudaibiya was signed between the Prophet (PBUH) and the Quraysh in Dhul Qadah 6 AH (628 CE).', 'The Quran calls it a clear victory (Fath-e-Mubin) in Surah Al-Fath.', 2),
    ('Hakeem Force Academy', 'In which language did Shah Abdul Latif Bhittai write poetry?', ['Punjabi', 'Sindhi', 'Urdu', 'Balochi'], 1, 'Shah Abdul Latif Bhittai (1689-1752) is the great Sufi poet of the Sindhi language.', 'His famous collection of poetry is called Shah Jo Risalo.', 4),
    ('Hakeem Force Academy', 'In which month did the 1965 Pakistan-India war take place and how long did it last?', ['August, 10 days', 'September, 17 days', 'December, 13 days', 'March, 21 days'], 1, 'The war began on 6 September 1965 when India crossed the international border at Lahore, and ended with a ceasefire on 23 September 1965, a total of 17 days.', 'Pakistan celebrates 6 September every year as Defence Day.', 6),
    ('Hakeem Force Academy', 'In which Islamic month is Eid ul Azha celebrated?', ['Ramadan', 'Shawwal', 'Dhul Hijjah', 'Muharram'], 2, 'Eid ul Azha is celebrated on 10 Dhul Hijjah, the twelfth month of the Islamic calendar, to remember the sacrifice of Hazrat Ibrahim (AS).', 'Eid ul Fitr falls on 1 Shawwal.', 4),
    ('Hakeem Force Academy', 'In which Islamic month was the Quran first revealed?', ['Muharram', 'Rajab', 'Ramadan', 'Shaban'], 2, 'The Quran began to be revealed in the month of Ramadan, on Laylat ul Qadr, in the cave of Hira.', 'The first revealed verses are the opening of Surah Al-Alaq.', 4),
    ('Hakeem Force Academy', 'In which months does the monsoon season occur in Pakistan?', ['December to February', 'July to September', 'March to May', 'October to November'], 1, 'The monsoon rains reach Pakistan in July and last until about September.', 'Most of the monsoon rain falls in the northern and north-eastern parts of the country.', 3),
]
